if (result.LastEvaluatedKey) {
  // 클라이언트에 전달하기 전에 키 형식 확인
  const nextKey = {
    partId: result.LastEvaluatedKey.partId?.S || result.LastEvaluatedKey.partId,
    // 필요한 다른 키도 추가
  };
  response.nextToken = Buffer.from(JSON.stringify(nextKey)).toString('base64');
}

// 클라이언트 요청 시 토큰 복원
