## ✅ 해결책 (우선순위 순)

### 1단계: 입력값 검증 강화 (ContactInquiryFunction)
```javascript
// contactInquiry.js
const validateSubject = (subject) => {
  // null/undefined 체크
  if (!subject) {
    throw new Error('Subject는 필수입니다');
  }

  // 공백만 있는 경우 제거
  const trimmed = subject.trim();
  if (trimmed.length === 0) {
    throw new Error('Subject는 공백만으로 구성될 수 없습니다');
  }

  // 길이 제한 (보통 SES는 255자 이하)
  if (trimmed.length > 255) {
    throw new Error('Subject는 255자 이하여야 합니다');
  }

  return trimmed;
};
```

